<script setup lang="ts">
import {useQuery,useQueryClient} from '@tanstack/vue-query'
import type {Project} from '~~/shared/types/projects'
import type {ProjectContractInput,ProjectContract,ProjectContractRegistry} from '~~/shared/types/project-contracts'
import {projectContractSchema,contractFigures,contractConflict} from '~~/shared/utils/project-contracts'
const props=defineProps<{project:Project}>(),auth=useAuthStore(),client=useQueryClient(),supabase=useNuxtApp().$supabase
const{query:estimate}=useProjectEstimateData(()=>props.project.id)
const key=computed(()=>['account',auth.user?.id,'project-contracts',props.project.id])
const registry=useQuery({queryKey:key,queryFn:({signal})=>sharedRequest<ProjectContractRegistry>(`/api/projects/${props.project.id}/contracts`,{signal}),retry:false,refetchInterval:30000})
const editable=computed(()=>props.project.permission!=='viewer'),rows=computed(()=>registry.data.value?.contracts??[]),parties=computed(()=>estimate.data.value?.counterparties??[])
const search=ref(''),open=ref(false),busy=ref(false),error=ref(''),exporting=ref(''),selected=ref<ProjectContract|null>(null),estimateRevision=ref(0),deleteOpen=ref(false)
const fresh=():ProjectContractInput=>({code:String(Math.max(0,...rows.value.map(row=>Number(row.code)||0))+1).padStart(2,'0'),number:'',sellerId:'',buyerId:'',date:new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow'}).format(new Date()),deadline:'',source:'revenue',itemIds:[]})
const draft=ref<ProjectContractInput>(fresh())
const visible=computed(()=>rows.value.filter(row=>`${row.code} ${row.number} ${row.seller} ${row.buyer}`.toLocaleLowerCase('ru').includes(search.value.toLocaleLowerCase('ru').trim())))
const figures=computed(()=>estimate.data.value?contractFigures(estimate.data.value,draft.value):null)
const available=computed(()=>estimate.data.value?.items.filter(item=>item.counterpartyId===draft.value.sellerId&&!item.internalCost)??[])
const conflict=computed(()=>contractConflict(draft.value,rows.value,selected.value?.id))
const money=(value:number|null)=>value===null?'—':value.toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽'
const date=(value:string)=>value?value.split('-').reverse().join('.'):'—'
function forbidden(id:string,other:string){const a=parties.value.find(party=>party.id===id),b=parties.value.find(party=>party.id===other);return id===other||!!(a?.isOwnLegalEntity&&b?.isOwnLegalEntity)}
const sellerOptions=computed(()=>parties.value.map(party=>({value:party.id,label:party.company+(party.isOwnLegalEntity?' · Наше юр. лицо':''),inn:party.inn,description:party.inn?'ИНН '+party.inn:'',disabled:forbidden(party.id,draft.value.buyerId)})))
const buyerOptions=computed(()=>parties.value.map(party=>({value:party.id,label:party.company+(party.isOwnLegalEntity?' · Наше юр. лицо':''),inn:party.inn,description:party.inn?'ИНН '+party.inn:'',disabled:forbidden(party.id,draft.value.sellerId)})))
function itemUsed(id:string){return rows.value.some(row=>row.id!==selected.value?.id&&row.itemIds.includes(id))}
async function show(row?:ProjectContract){await estimate.refetch();estimateRevision.value=estimate.data.value?.revision??0;selected.value=row??null;draft.value=row?{code:row.code,number:row.number,sellerId:row.sellerId,buyerId:row.buyerId,date:row.date,deadline:row.deadline,source:row.source,itemIds:[...row.itemIds]}:fresh();error.value='';open.value=true}
function toggle(id:string,checked:boolean){draft.value.itemIds=checked?[...draft.value.itemIds,id]:draft.value.itemIds.filter(item=>item!==id)}
async function refresh(){await Promise.all([client.invalidateQueries({queryKey:key.value}),client.invalidateQueries({queryKey:['account',auth.user?.id,'project-estimate']})])}
async function submit(remove=false){
 if(busy.value||!editable.value)return
 error.value='';const parsed=projectContractSchema.safeParse(draft.value)
 if(!remove&&(!parsed.success||figures.value?.issue||conflict.value)){error.value=!parsed.success?parsed.error.issues[0]?.message||'Проверьте поля':figures.value?.issue||conflict.value;return}
 busy.value=true;const userId=auth.user?.id
 try{await sharedRequest(`/api/projects/${props.project.id}/contracts${selected.value?'/'+selected.value.id:''}`,{method:remove?'DELETE':selected.value?'PUT':'POST',body:remove?{revision:selected.value!.revision,estimateRevision:estimateRevision.value}:{contract:parsed.data,estimateRevision:estimateRevision.value,...(selected.value?{revision:selected.value.revision}:{})}});if(auth.user?.id!==userId)return;open.value=false;deleteOpen.value=false;await refresh()}
 catch(failure:any){error.value=failure?.data?.message||failure.message;if(failure?.statusCode===409)await refresh()}
 finally{busy.value=false}
}
async function download(format:'xlsx'|'pdf'){
 if(exporting.value)return;exporting.value=format;error.value='';const userId=auth.user?.id
 try{const{data}=await supabase.auth.getSession();if(!data.session||data.session.user.id!==userId)throw Error('Войдите в аккаунт');const blob=await $fetch<Blob>(`/api/projects/${props.project.id}/contracts/export`,{method:'POST',retry:0,responseType:'blob',headers:{Authorization:`Bearer ${data.session.access_token}`},body:{format}});if(auth.user?.id!==userId)return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`Договора — ${props.project.name.replace(/[\\/:*?"<>|]/g,'-')}.${format}`;document.body.appendChild(link);link.click();link.remove();window.setTimeout(()=>URL.revokeObjectURL(url),10000)}catch(failure:any){if(failure?.data instanceof Blob){try{error.value=JSON.parse(await failure.data.text()).message}catch{error.value='Не удалось скачать реестр'}}else error.value=failure?.data?.message||failure.message}finally{exporting.value=''}
}
watch(editable,value=>{if(!value){open.value=false;deleteOpen.value=false}})
</script>
<template>
 <section class="contracts-workspace" aria-label="Договора проекта"><div class="contracts-intro"><div><h2>Реестр договоров</h2><p>Суммы и НДС рассчитываются из сметы и обновляются вместе с ней.</p></div><NuxtLink :to="`/projects/${project.id}/estimate`" class="subscription-card-link">Открыть смету →</NuxtLink></div>
 <div class="contracts-toolbar"><UInput v-model="search" icon="i-lucide-search" placeholder="Номер, продавец или покупатель" aria-label="Поиск договора" class="contracts-search"/><UButton label="Excel" icon="i-lucide-file-spreadsheet" color="neutral" variant="outline" :loading="exporting==='xlsx'" :disabled="!!exporting||registry.isPending.value||!!registry.error.value" @click="download('xlsx')"/><UButton label="PDF" icon="i-lucide-file-text" color="neutral" variant="outline" :loading="exporting==='pdf'" :disabled="!!exporting||registry.isPending.value||!!registry.error.value" @click="download('pdf')"/><UButton v-if="editable" label="Добавить договор" icon="i-lucide-plus" :disabled="estimate.isPending.value||!!estimate.error.value" @click="show()"/></div>
 <UAlert v-if="error&&!open" color="error" :description="error" class="mb-4"/><UAlert v-if="registry.error.value||estimate.error.value" color="error" title="Не удалось загрузить данные договоров" :actions="[{label:'Повторить',onClick:refresh}]"/><p v-else-if="registry.isPending.value||estimate.isPending.value" class="contracts-muted">Загружаем договоры…</p><div v-else-if="visible.length" class="contracts-scroll" tabindex="0" aria-label="Реестр договоров, прокручивается горизонтально"><table><thead><tr><th>Код</th><th>Номер</th><th>Продавец / исполнитель</th><th>Покупатель / заказчик</th><th>Дата</th><th>Срок</th><th>Сумма с НДС, ₽</th><th>НДС, ₽</th><th v-if="editable">Действия</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td>{{row.code}}</td><td><strong>{{row.number}}</strong><small>{{row.source==='revenue'?'Выручка сметы':'Расходы сметы'}}</small><span v-if="row.issue" class="contract-issue">{{row.issue}}</span></td><td>{{row.seller}}</td><td>{{row.buyer}}</td><td>{{date(row.date)}}</td><td>{{date(row.deadline)}}</td><td>{{money(row.amount)}}</td><td>{{money(row.vatAmount)}}</td><td v-if="editable"><UButton icon="i-lucide-pencil" :aria-label="`Изменить договор ${row.number}`" color="neutral" variant="ghost" @click="show(row)"/></td></tr></tbody></table></div><div v-else class="contracts-empty"><UIcon name="i-lucide-file-signature"/><h2>{{search?'Договоры не найдены':'Добавьте первый договор проекта'}}</h2><p>Выберите стороны и источник суммы из сметы. Реквизиты используются из общей базы компаний проекта.</p><UButton v-if="editable&&!search" label="Добавить договор" icon="i-lucide-plus" @click="show()"/></div>
 </section>
 <UModal v-model:open="open" :title="selected?'Изменить договор':'Добавить договор'" description="Сумма и НДС берутся из сметы. Вводить их вручную в договоре не нужно." :dismissible="!busy" :ui="{content:'sm:max-w-4xl'}"><template #body><form id="project-contract-form" class="contract-form" @submit.prevent="submit()"><label>Код<input v-model="draft.code" maxlength="30" :disabled="busy"/></label><label>Номер договора<input v-model="draft.number" maxlength="100" required :disabled="busy"/></label><label>Продавец / исполнитель<USelectMenu v-model="draft.sellerId" :items="sellerOptions" value-key="value" :filter-fields="['label','inn']" :search-input="{placeholder:'Название или ИНН'}" placeholder="Выберите компанию" aria-label="Продавец / исполнитель" :disabled="busy" class="w-full" @update:model-value="draft.itemIds=[]"/></label><label>Покупатель / заказчик<USelectMenu v-model="draft.buyerId" :items="buyerOptions" value-key="value" :filter-fields="['label','inn']" :search-input="{placeholder:'Название или ИНН'}" placeholder="Выберите компанию" aria-label="Покупатель / заказчик" :disabled="busy" class="w-full"/></label><label>Дата договора<input v-model="draft.date" type="date" :disabled="busy"/></label><label>Срок<input v-model="draft.deadline" type="date" :disabled="busy"/></label><label class="full">Источник суммы<select v-model="draft.source" :disabled="busy" @change="draft.itemIds=[]"><option value="revenue">Выручка проекта из сметы</option><option value="expenses">Выбранные расходы поставщика из сметы</option></select></label><section v-if="draft.source==='expenses'" class="full contract-items"><h3>Позиции из сметы</h3><p v-if="!available.length" class="contracts-muted">В смете нет позиций выбранного продавца / исполнителя. Сначала добавьте их в смету или выберите другого поставщика.</p><label v-for="item in available" :key="item.id"><input type="checkbox" :checked="draft.itemIds.includes(item.id)" :disabled="busy||itemUsed(item.id)" @change="toggle(item.id,($event.target as HTMLInputElement).checked)"/><span>{{item.name}} <small>{{itemUsed(item.id)?'Уже используется в другом договоре':`${item.quantity.toLocaleString('ru-RU')} × ${money(item.price)}`}}</small></span></label></section><div class="full contract-preview"><div><small>Сумма с НДС</small><strong>{{money(figures?.amount??null)}}</strong></div><div><small>НДС из сметы</small><strong>{{money(figures?.vatAmount??null)}}</strong></div><div><small>Без НДС</small><strong>{{money(figures?.netAmount??null)}}</strong></div></div><UAlert v-if="figures?.issue||conflict" color="neutral" :description="figures?.issue||conflict" class="full"/><p v-if="parties.length<2" class="full contracts-muted">Добавьте контрагентов и наши юрлица на странице проекта.</p><UAlert v-if="error" color="error" :description="error" class="full"/></form></template><template #footer><div class="contract-footer"><UButton v-if="selected" label="Удалить договор" color="error" variant="ghost" :disabled="busy" @click="deleteOpen=true"/><UButton label="Отмена" color="neutral" variant="outline" :disabled="busy" @click="open=false"/><UButton label="Сохранить договор" type="submit" form="project-contract-form" :loading="busy" :disabled="!!figures?.issue||!!conflict"/></div></template></UModal>
 <UModal v-model:open="deleteOpen" title="Удалить договор?" :description="`Договор «${selected?.number??''}» будет удалён из реестра. Позиции сметы сохранятся.`" :dismissible="!busy"><template #footer><UButton label="Отмена" color="neutral" variant="outline" :disabled="busy" @click="deleteOpen=false"/><UButton label="Удалить" color="error" :loading="busy" @click="submit(true)"/></template></UModal>
</template>
<style scoped>
.contracts-workspace{min-width:0}.contracts-intro{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:24px}.contracts-intro h2{font-weight:600;font-size:22px;color:#334155}.contracts-intro p,.contracts-muted{font-size:13px;line-height:1.7;color:#94a3b8;margin-top:10px}.contracts-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:24px}.contracts-search{flex:1;min-width:230px}.contracts-scroll{overflow:auto;border:1px solid #e2e8f0;border-radius:18px;background:white}.contracts-scroll table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}.contracts-scroll th{white-space:nowrap;color:#64748b;font-weight:600;background:#f4f7fa}.contracts-scroll td,.contracts-scroll th{padding:17px;border-bottom:1px solid #e2e8f0;min-width:105px;max-width:300px;overflow-wrap:anywhere}.contracts-scroll td{color:#475569}.contracts-scroll td small{display:block;color:#94a3b8;font-size:11px;margin-top:7px}.contracts-scroll tr:last-child td{border:0}.contract-issue{display:block;color:#dc2626;font-size:11px;margin-top:8px}.contracts-empty{text-align:center;border:1px solid #e2e8f0;border-radius:22px;padding:65px 24px;background:#ffffffa3}.contracts-empty>.iconify{font-size:38px;color:var(--ui-primary)}.contracts-empty h2{font-weight:600;font-size:22px;color:#475569;margin:20px 0 10px}.contracts-empty p{font-size:14px;color:#94a3b8;max-width:480px;line-height:1.7;margin:0 auto 24px}.contract-form{display:grid;grid-template-columns:1fr 1fr;gap:20px}.contract-form>label{display:flex;flex-direction:column;gap:8px;font-size:13px;color:#475569}.contract-form input:not([type=checkbox]),.contract-form select{padding:10px 12px;min-width:0;width:100%;border:1px solid #cbd5e1;border-radius:8px;background:white;outline-color:var(--ui-primary)}.contract-form .full{grid-column:1/-1}.contract-items{border-top:1px solid #e2e8f0;padding-top:20px}.contract-items h3{font-weight:600;color:#475569;margin-bottom:12px}.contract-items label{display:flex;gap:12px;align-items:center;padding:12px 0;font-size:13px;color:#475569}.contract-items label small{display:block;color:#94a3b8;margin-top:5px}.contract-items input{accent-color:var(--ui-primary)}.contract-preview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;background:#f4f6f9;padding:20px;border-radius:14px}.contract-preview small{display:block;font-size:11px;color:#94a3b8;margin-bottom:8px}.contract-preview strong{font-size:19px;color:#334155;overflow-wrap:anywhere}.contract-footer{display:flex;gap:12px;justify-content:flex-end;flex-wrap:wrap;width:100%}@media(max-width:700px){.contract-form{grid-template-columns:1fr}.contract-preview{grid-template-columns:1fr}.contracts-intro{flex-direction:column}.contracts-search{flex-basis:100%}}
</style>
